const { Client } = require('pg');
const https = require('https');

const connectionString = process.env.DATABASE_URL;
const geminiApiKey = process.env.GEMINI_API_KEY;

function postJson(url, data) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const body = JSON.stringify(data);

    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      }
    };

    const req = https.request(urlObj, options, (res) => {
      let responseBody = '';
      res.on('data', chunk => responseBody += chunk);
      res.on('end', () => {
        try {
          resolve({ statusCode: res.statusCode, body: JSON.parse(responseBody), raw: responseBody });
        } catch (e) {
          resolve({ statusCode: res.statusCode, error: 'Failed to parse JSON', raw: responseBody });
        }
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  if (!connectionString) throw new Error('Missing DATABASE_URL env variable');
  if (!geminiApiKey) throw new Error('Missing GEMINI_API_KEY env variable');

  const pgClient = new Client({
    connectionString,
    ssl: { rejectUnauthorized: false }
  });

  await pgClient.connect();

  try {
    const insightsRes = await pgClient.query('SELECT i.*, m.product_category, m.product_name, m.product_ref, a.classification, a.breakout_score FROM post_performance_insights i LEFT JOIN post_product_mapping m ON i.platform_post_id = m.platform_post_id LEFT JOIN post_performance_analytics a ON i.platform_post_id = a.platform_post_id ORDER BY i.published_at DESC;');
    const categoryRes = await pgClient.query('SELECT * FROM category_performance_analytics;');

    const posts = insightsRes.rows;
    const categories = categoryRes.rows;

    const promptData = {
      businessName: 'AME Bazaar',
      location: 'Kirari, Delhi',
      objective: 'Increase qualified physical store footfall and local customer discovery.',
      historicalPosts: posts.map(p => ({
        platform: p.platform,
        published_at: p.published_at,
        reach: p.reach,
        likes: p.likes,
        comments: p.comments,
        shares: p.shares,
        saves: p.saves,
        category: p.product_category || 'UNMAPPED',
        product_name: p.product_name || 'N/A',
        classification: p.classification || 'INSUFFICIENT_DATA'
      })),
      categoryAnalytics: categories
    };

    const systemInstructions = 'You are the Autonomous Growth Strategy Brain v1 for AME Bazaar in Kirari, Delhi. Generate a structured Daily Organic Growth Strategy. Focus on driving physical store footfall (local customer discovery). Return a JSON object conforming exactly to this structure: { "current_situation": "Text summary.", "winners": "Text summary.", "weak_signals": "Text description.", "recommended_mix": { "WOMEN": "40%", "MEN": "30%", "BOYS": "30%" }, "content_ideas": [ { "category_product": "WOMEN", "format": "REEL", "hook": "Hinglish hook", "customer_problem": "Problem solved", "cta": "WhatsApp CTA", "evidence": "Citing data or exploration need" } ], "experiments": ["Experiment 1"], "learning_priorities": ["Priority 1"], "confidence": "LOW or MEDIUM or HIGH", "footfall_strategy": "Footfall strategy text." } Keep all descriptions brief and concise to prevent any API output limits. Do NOT wrap the JSON in Markdown formatting (no backticks).';

    const url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + geminiApiKey;
    const payload = {
      contents: [
        {
          role: 'user',
          parts: [
            { text: systemInstructions },
            { text: 'Data Context:\n' + JSON.stringify(promptData) }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        responseMimeType: 'application/json'
      }
    };

    const response = await postJson(url, payload);
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw new Error('Gemini API responded with code ' + response.statusCode + ': ' + response.raw);
    }

    const result = response.body;
    const candidates = result.candidates || [];
    let rawText = '';
    if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
      rawText = candidates[0].content.parts.map(p => p.text || '').join('\n').trim();
    }

    if (!rawText) throw new Error('Empty response from Gemini.');

    const parsedStrategy = JSON.parse(rawText.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim());
    const todayDate = new Date().toISOString().split('T')[0];

    const upsertSql = 'INSERT INTO growth_strategy_recommendations (strategy_date, recommendation, confidence, evidence, created_at) VALUES ($1, $2, $3, $4, now()) ON CONFLICT (strategy_date) DO UPDATE SET recommendation = EXCLUDED.recommendation, confidence = EXCLUDED.confidence, evidence = EXCLUDED.evidence, created_at = now() RETURNING id;';

    const dbRes = await pgClient.query(upsertSql, [
      todayDate,
      parsedStrategy,
      parsedStrategy.confidence,
      JSON.stringify(promptData)
    ]);

    await pgClient.end();
    return [{ json: { success: true, strategy_date: todayDate, dbId: dbRes.rows[0].id } }];
  } catch (err) {
    await pgClient.end();
    throw err;
  }
}
